import { defineSchema, lazySchema } from "../../../src/schemas/index.js";
import { createArgParser, parseArgsOrThrow } from "../../shared/args.js";
import { exitProcess, logSuccess } from "../../utils/index.js";
import { runCommand } from "../../../src/platform/compat/process/command.js";
import { createErrorEnvelope, createSuccessEnvelope, isJsonMode, outputJson, } from "../../shared/json-output.js";
import { parseTestOutput } from "./command.js";
const getTestArgsSchema = defineSchema((v) => v.object({
    filter: v.string().optional(),
    parallel: v.boolean().default(false),
}));
const TestArgsSchema = lazySchema(getTestArgsSchema);
const parseTestArgs = createArgParser(TestArgsSchema, {
    filter: { keys: ["filter"], type: "string", positional: 0 },
    parallel: { keys: ["parallel"], type: "boolean" },
});
export async function handleTestCommand(args) {
    const opts = parseArgsOrThrow(parseTestArgs, "test", args);
    const result = await runCommand("deno", {
        args: [
            "test",
            "--no-check",
            "--allow-all",
            "--unstable-worker-options",
            "--unstable-net",
            ...(opts.parallel ? ["--parallel"] : []),
            ...(opts.filter ? [`--filter=${opts.filter}`] : []),
        ],
        capture: true,
        env: {
            VF_DISABLE_LRU_INTERVAL: "1",
            SSR_TRANSFORM_PER_PROJECT_LIMIT: "0",
            REVALIDATION_PER_PROJECT_LIMIT: "0",
            NODE_ENV: "production",
            LOG_FORMAT: "text",
        },
    });
    const stdout = result.stdout ?? "";
    const stderr = result.stderr ?? "";
    const fullOutput = stdout + "\n" + stderr;
    const parsed = parseTestOutput(fullOutput, result.code);
    const noTestModules = result.code !== 0 && parsed.success &&
        fullOutput.includes("No test modules found");
    if (isJsonMode()) {
        if (parsed.success) {
            await outputJson(createSuccessEnvelope("test", parsed));
        }
        else {
            await outputJson(createErrorEnvelope("test", {
                code: "TEST_FAILURE",
                slug: "tests-failed",
                message: `${parsed.summary.failed} test(s) failed`,
                context: parsed,
            }));
        }
    }
    else {
        if (noTestModules) {
            logSuccess("No test modules found.");
        }
        else {
            if (stdout)
                console.log(stdout);
            if (stderr)
                console.error(stderr);
        }
    }
    exitProcess(parsed.success ? 0 : result.code);
}
